  memcpy(&g_imu_ring[head % PROBE_IMU_RING_DEPTH], sample, sizeof(*sample));
  __atomic_store_n(&g_imu_head, head + 1, __ATOMIC_RELEASE);
  if ((sample->flags & PROBE_IMU_SAMPLE_FLAG_GAP) != 0)
