bool probe_game_take_ble_result(struct probe_game_result *result)
{
  uint32_t tail = __atomic_load_n(&g_result_tail, __ATOMIC_RELAXED);
  uint32_t head = __atomic_load_n(&g_result_head, __ATOMIC_ACQUIRE);

  if (tail == head)
