#!/usr/bin/env python3
"""Exercise the serial BEAT1 command/ack loop; not an action recognizer."""
import argparse, binascii, struct, time
import serial

def crc16(data):
    c = 0xffff
    for b in data:
        c ^= b
        for _ in range(8): c = (c >> 1) ^ 0xa001 if c & 1 else c >> 1
    return c

def frame(session, event):
    p = struct.pack('<BBII', 1, 1, session, event)
    return f'@BEAT1,10,{p.hex()},{crc16(p):04x}\n'.encode()

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--serial-port', default='COM7'); ap.add_argument('--baud', type=int, default=1000000)
    ap.add_argument('--events', type=int, default=10); ap.add_argument('--timeout-s', type=float, default=3)
    ap.add_argument('--duplicate-event', type=int, default=3); ap.add_argument('--raw-log', default='beat_link_raw.bin')
    a = ap.parse_args()
    with serial.Serial(a.serial_port, a.baud, timeout=.1) as s, open(a.raw_log, 'wb') as raw:
        deadline = time.monotonic() + a.timeout_s; buf = b''; session = None
        while time.monotonic() < deadline and session is None:
            b = s.read(256); raw.write(b); buf += b
            for line in buf.splitlines(True):
                if line.endswith(b'\n') and line.startswith(b'@IMU1,READY,'):
                    session = int(line.decode(errors='ignore').split(',')[3]); break
            buf = buf[buf.rfind(b'\n') + 1:] if b'\n' in buf else buf
        if session is None: raise SystemExit('READY not received')
        ids = list(range(1, a.events + 1)); ids.insert(min(a.duplicate_event, len(ids)), a.duplicate_event)
        for event in ids: s.write(frame(session, event)); time.sleep(.05)
        end = time.monotonic() + a.timeout_s; acks = []
        while time.monotonic() < end:
            b = s.read(512); raw.write(b); buf += b
            while b'\n' in buf:
                line, buf = buf.split(b'\n', 1)
                if line.startswith(b'@BEAT1_ACK,'): acks.append(line.decode(errors='replace'))
        print(f'session={session} acknowledgements={len(acks)}')
        print('\n'.join(acks))
if __name__ == '__main__': main()
