              if (g_beat_recent_count < PROBE_BEAT_RECENT_DEPTH) g_beat_recent_count++;
              g_beat_count++; }
          probe_serial_ack(duplicate ? 1 : 0, eid);
        }
      else if (used + 1 < sizeof(line)) line[used++] = ch;
      else { used = 0; g_beat_errors++; probe_serial_ack(2, 0); }
