#!/usr/bin/env python3
"""Cold-start serial BEAT1 loop test; not an action recognizer."""
import argparse, struct, time
from pathlib import Path
import serial

def crc16(data):
    c = 0xffff
    for b in data:
        c ^= b
        for _ in range(8): c = (c >> 1) ^ 0xa001 if c & 1 else c >> 1
    return c

def frame(session, event):
    p = struct.pack('<BBII', 1, 1, session, event)
    return f'@BEAT1,10,{p.hex()},{crc16(p):04x}\n'.encode()

def parse_ready(line):
    if not line.startswith(b'@IMU1,READY,'): return None
    try: return int(line.decode('ascii').split(',')[3], 10)
    except (ValueError, IndexError): return None

def parse_ack(line):
    if not line.startswith(b'@BEAT1_ACK,'): return None
    p = line.decode('ascii').strip().split(',')
    if len(p) != 5: return None
    try: return tuple(int(x, 10) for x in p[1:5])
    except ValueError: return None

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--serial-port', default='COM7'); ap.add_argument('--baud', type=int, default=1000000)
    ap.add_argument('--events', type=int, default=10); ap.add_argument('--startup-timeout-s', type=float, default=8)
    ap.add_argument('--ack-timeout-s', type=float, default=4); ap.add_argument('--duplicate-event', type=int, default=3)
    ap.add_argument('--raw-log', default='beat_link_raw.bin'); ap.add_argument('--startup-command', default='openvela_ble_probe\n')
    a = ap.parse_args()
    with serial.Serial(a.serial_port, a.baud, timeout=.1) as s, Path(a.raw_log).open('wb') as raw:
        buf = b''; session = None; prompt = False
        def read_until(deadline):
            nonlocal buf, session, prompt
            while time.monotonic() < deadline:
                b = s.read(512)
                if b: raw.write(b); buf += b
                while b'\n' in buf:
                    line, buf = buf.split(b'\n', 1)
                    prompt = prompt or b'nsh>' in line
                    q = parse_ready(line + b'\n')
                    if q is not None: session = q
            return session
        read_until(time.monotonic() + a.startup_timeout_s)
        if session is None and prompt:
            s.write(a.startup_command.encode('ascii'))
            read_until(time.monotonic() + a.startup_timeout_s)
        if session is None:
            raise SystemExit('未收到READY；若无nsh>则请冷启动，未发送启动命令；若已有程序运行，请先退出并冷启动。')
        ids = list(range(1, a.events + 1)); ids.insert(min(max(a.duplicate_event - 1, 0), len(ids)), a.duplicate_event)
        for event in ids: s.write(frame(session, event)); time.sleep(.05)
        end = time.monotonic() + a.ack_timeout_s; acks = []
        while time.monotonic() < end:
            b = s.read(512)
            if b: raw.write(b); buf += b
            while b'\n' in buf:
                line, buf = buf.split(b'\n', 1); q = parse_ack(line)
                if q is not None: acks.append(q)
        print(f'session={session} acknowledgements={len(acks)} raw_log={a.raw_log}')
        for q in acks: print(f'ACK session={q[0]} event={q[1]} status={q[2]} accepted_count={q[3]}')
        if len(acks) < len(ids): raise SystemExit('ACK timeout; raw log retained')
if __name__ == '__main__': main()

